// core.js as TypeScript declarations, written by hand; keep them with the JSDoc in core.js. The
// Document, the snapshot and the catalog are rnl-view's, generated by ts-rs
// (crates/rnl-view/types/document.d.ts, snapshot.d.ts and catalog.d.ts), which build.mjs copies
// next to this file.

import type { Catalog } from "./catalog.js";
import type { Document, FormatInfo, UnplacedDrawing } from "./document.js";
import type { Snapshot } from "./snapshot.js";

export type { Catalog, Document, FormatInfo, Snapshot, UnplacedDrawing };

/** Inspection SVG export styles, independent of RNL language styles. */
export interface OverlayStyle {
  palette?: string[];
  width?: number;
  dashes?: number[];
  current_color?: string;
}
export interface OverlayOptions {
  usages?: "none" | "semantic" | "all";
  currents?: boolean;
  roles?: boolean;
  style?: OverlayStyle;
}

/** What to build: the workspace and how. Fields the core does not know are ignored. */
export interface Request {
  /** Opt-in SVG overlays. Level.usages[].frame and Level.currents always give geometry. */
  overlays?: OverlayOptions;
  /** The path of the file to open, as the frontend names it, such as `/w/top.sp`. */
  entry: string;
  /** The texts of the workspace by path, the entry's among them. */
  files?: Record<string, string>;
  /** The directories, among the paths of `files`, whose packages are found by name (16.2). */
  package_dirs?: string[];
  /** Explicit temporary files, searched before package directories. */
  pool?: string[];
  /** Opt-in indexed lookup of undefined subcircuits. */
  auto_include?: boolean;
  /** The browser's internal pool namespace. */
  library_prefix?: string;
  /** Applied overrides, by canonical library path. */
  library_edits?: Record<string, string>;
  /** The format of the entry, instead of guessing it from the entry. */
  dialect?: "spice" | "spectre";
  /**
   * The format set for files, by path as in `files`: only those the user set, each a name of
   * `FormatInfo.name`. A file not among them is read by its own suffix and first lines. An unknown
   * name fails the build, so leave out the names the core does not list. The library index reads
   * its files with them too.
   */
  formats?: Record<string, string>;
  /** Use the standard package at the root (16.3); true when not given. */
  std?: boolean;
  /**
   * The version of the standard package at the root, whatever the files' language version, such
   * as "0.2" to read a file of 0.3 with the series 0.2; a version pinned in a header record still
   * comes first (16.3). By the language version when not given.
   */
  std_version?: string;
  /** Write each level's SVG; true when not given. */
  svg?: boolean;
  /** Give each level's primitives; false when not given. */
  primitives?: boolean;
  /**
   * Give each level its solve status, `solve`, what a frontend decides from whether to solve it
   * (decision 0008): "fixed", "unsolved", "solved" or "stale"; false when not given.
   */
  status?: boolean;
  /**
   * Leave the drawings of the objects without a position, `Level.unplaced[].svg` and `primitives`,
   * out of the Document and keep them to give on request (`DrawingsRequest`), until the next build
   * that asks for it; false, the Document carrying them, when not given.
   */
  lazy_unplaced?: boolean;
  /**
   * The parts of the editor interface's snapshot to give: with them, the answer is a Snapshot,
   * with the Document as its `drawing` unless `drawing` is false.
   */
  parts?: { drawing?: boolean; host?: boolean; model?: boolean };
}

export type Point = [number, number];

/** A style property's value. */
export type Literal = string | number | boolean;

/** A vertex of a wire: a pin, a named point, a role of a usage, or coordinates. */
export type Vertex = { terminal: string } | { point: string } | { usage: string; role: string } | { at: Point };

/** A run of a line of text, as the Document's `Text.lines` holds it (13.6). */
export type Run =
  | { kind: "text"; text: string; style: RunStyle }
  | { kind: "frac"; num: Run[]; den: Run[]; style: RunStyle };

export interface RunStyle {
  level: number;
  bold: boolean;
  italic: boolean;
  overline: boolean;
}

/**
 * An op of an edit transaction, as the editor interface draft writes them (4.1): those the writer
 * writes so far. `level` is `subckt:NAME` or `file:PATH`; a `use-package` goes into the header
 * record, whatever its level.
 */
export type Op = { level?: string } & (
  | { op: "set"; object: string; symbol?: string; at?: Point; orient?: string }
  | {
      op: "add-usage";
      name?: string;
      definition: string;
      /**
       * Each role by its name, with the id of the object or the point it fills, written `#M1(in_p)`;
       * a set role (9.4) with the list of its members, written `{#M3 #M9}(ref)`, `{}` for none.
       */
      attach: Record<string, string | Point | (string | Point)[]>;
      symbol?: string;
      at?: Point;
      orient?: string;
    }
  | { op: "add-point"; name: string; at: Point; junction?: boolean }
  | { op: "add-wire"; name?: string; nets: string[]; via: Vertex[]; mode?: string; style?: Record<string, Literal> }
  | {
      op: "add-text";
      name?: string;
      attach?: string;
      key?: string;
      markup?: string;
      lines?: Run[][];
      at?: Point;
      offset?: Point;
      /**
       * `halign`, `valign` and `rotate` are written as given for a text with a `key`, whose value
       * left out is the one its symbol gives that key (13.3). For a text without a key, a value
       * equal to the default (`"start"`, `"baseline"`, 0) is left out.
       */
      halign?: string;
      valign?: string;
      rotate?: number;
      size?: number;
      style?: Record<string, Literal>;
    }
  | { op: "add-to" | "remove-from"; items: string[]; set: string }
  | { op: "use-package"; name: string; version?: string; path?: string }
  | ({ op: "add-shape"; name?: string; layer?: "bottom" | "middle" | "top" } & Shape)
  | {
      op: "define-symbol";
      /** `$NAME`, or `%NAME` for a symbol of the level, such as a subcircuit's block. */
      name: string;
      box?: [number, number, number, number];
      pins: SymbolPin[];
      /** The symbol's graphics, in its own coordinates. */
      prims: Shape[];
    }
);

/**
 * A graphic (9.2.5): a rectangle, circle or ellipse by its centre and its size (width and height,
 * or radius), or by two points; a line by two points or more, an arc by three, a Bezier curve by
 * 3n+1.
 */
export interface Shape {
  shape: "line" | "rectangle" | "circle" | "ellipse" | "arc" | "bezier";
  points: Point[];
  /** width, height, radius, fill ("none", "linecolor", "fillcolor") and arrow ("start", "end", "both"). */
  params?: Record<string, Literal>;
  /** Style properties such as linecolor, linestyle, linewidth, fillcolor and arrowsize. */
  style?: Record<string, Literal>;
}

/** A pin of a symbol (9.2.4). */
export interface SymbolPin {
  /** One terminal, or several for a bus pin, by number or by name. */
  terminals: (number | string)[];
  at: Point;
  direction?: "right" | "up" | "left" | "down";
  /** The pin's name for display. */
  label?: { markup: string } | { lines: Run[][] };
}

/** What to write: an edit transaction's ops into its netlist, and how to build what was written. */
export interface WriteRequest {
  overlays?: OverlayOptions;
  write: {
    dialect: "spice" | "spectre";
    /** The netlist, without RNL records. */
    netlist: string;
    /** The `author` of the records written. */
    author: string;
    ops: Op[];
    /**
     * The name the netlist is saved under, such as `top.net`, when it is known: a Spectre netlist
     * that is not a `.scs` file is read in the SPICE mode up to its `simulator lang=spectre`, and its
     * header and records go where that reading keeps them. Without it, a Spectre netlist is read as
     * a `.scs` file.
     */
    file?: string;
  };
  /** Further files, such as packages; the netlist is the entry. */
  files?: Record<string, string>;
  package_dirs?: string[];
  std?: boolean;
  std_version?: string;
  svg?: boolean;
  primitives?: boolean;
  status?: boolean;
}

/** The netlist a write wrote, and its Document, whose diagnostics say how it reads. */
export interface Written {
  text: string;
  document: Document;
}

/**
 * What to list: the catalog of the packages the core has, those of `package_dirs` among `files`
 * and the bundled ones under them, the standard series, each read as
 * `rnl check` reads a package file, checked on its own (2.7).
 */
export interface CatalogRequest {
  catalog: {
    /** Only the packages of these names; every package when not given. */
    packages?: string[];
    /** Every version of each package, not only the newest; false when not given. */
    all_versions?: boolean;
  };
  /** The frontend's files, among them its packages, as in a Request. */
  files?: Record<string, string>;
  /** The directories, among the paths of `files`, whose packages are listed (16.2). */
  package_dirs?: string[];
  /** Read each package with the standard package of its language version (16.3); true when not given. */
  std?: boolean;
  std_version?: string;
}

/**
 * What to draw: the objects at `items` of `levels[level].unplaced` of the Document that the last
 * build with `lazy_unplaced` gave, which the core kept the drawings of. `names`, when given, are
 * their names as the Document lists them, which the core checks: a request about a Document that
 * was built again is refused, not answered with other objects.
 */
export interface DrawingsRequest {
  drawings: { level: number; items: number[]; names?: string[] };
}

export interface LibraryRequest {
  library: { reload?: boolean; refresh?: string[] };
  pool: string[];
  files: Record<string, string>;
  /** The format set for files by path, as a build's `formats`: the index reads its files with them. */
  formats?: Record<string, string>;
}

/** What to list: the formats, and the format each file of `detect`, by path and text, has when none is set. */
export interface FormatsRequest {
  formats: { detect?: Record<string, string> };
}

/** What a formats request answers. */
export interface FormatList {
  list: FormatInfo[];
  /** The format of each file of `detect`, by its path. */
  detected: Record<string, string>;
}

/** The core, loaded. */
export interface Core {
  /** Build the Document of a request; throws an Error with the core's message when there is none. */
  build(request: Request | string): Document;
  /** Build the snapshot of a request with `parts`, as build builds the Document. */
  snapshot(request: Request | string): Snapshot;
  /** Write the ops into the netlist and build it; throws an Error when an op cannot be written. */
  write(request: WriteRequest | string): Written;
  /** List the symbols, definitions and sets of the packages the core has. */
  catalog(request: CatalogRequest | string): Catalog;
  /** The drawings of the objects a request names, from the last build that kept them; throws when none did. */
  drawings(request: DrawingsRequest | string): UnplacedDrawing[];
  /** Update the viewer library index; returns read errors. */
  library(request: LibraryRequest | string): string[];
  /** The formats a file can be read with, and the format each file of `detect` has when none is set. */
  formats(request: FormatsRequest | string): FormatList;
  /** The core's answer as it gives it; throws only when the core stops. */
  respond(
    request: Request | WriteRequest | CatalogRequest | DrawingsRequest | LibraryRequest | FormatsRequest | string,
  ):
    | { document: Document }
    | { snapshot: Snapshot }
    | { written: Written }
    | { catalog: Catalog }
    | { drawings: UnplacedDrawing[] }
    | { library: string[] }
    | { formats: FormatList }
    | { error: string };
}

/** Load the core: the module by URL, as a response, as bytes, or compiled. */
export function loadCore(wasm: string | URL | Response | BufferSource | WebAssembly.Module): Promise<Core>;

/** A request as the JSON text the core reads. */
export function requestText(
  request: Request | WriteRequest | CatalogRequest | DrawingsRequest | LibraryRequest | FormatsRequest,
): string;
